// ═══ OPTION 1: try-catch inside lambda (most common) ═══
List<String> results = trades.stream()
    .map(trade -> {
        try {
            return externalApi.settle(trade);  // throws SettlementException (checked)
        } catch (SettlementException e) {
            throw new RuntimeException("Settlement failed: " + trade.getId(), e);
            // or: return "FAILED:" + trade.getId();  // swallow and provide default
        }
    })
    .toList();

// ═══ OPTION 2: Custom @FunctionalInterface with throws ═══
@FunctionalInterface
interface ThrowingFunction<T, R> {
    R apply(T t) throws Exception;
}

// Wrapper that converts checked → unchecked:
static <T, R> java.util.function.Function<T, R> unchecked(ThrowingFunction<T, R> fn) {
    return t -> {
        try { return fn.apply(t); }
        catch (Exception e) { throw new RuntimeException(e); }
    };
}

// Usage — clean!
List<String> results = trades.stream()
    .map(unchecked(externalApi::settle))  // checked exception handled by wrapper
    .toList();

// ═══ OPTION 3: Sneaky throw (not recommended for production) ═══
@SuppressWarnings("unchecked")
static <E extends Throwable> void sneakyThrow(Throwable e) throws E {
    throw (E) e;  // bypasses compiler check via type erasure
}
