package com.bank.exceptions;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.function.Function;
import static org.assertj.core.api.Assertions.*;

class CheckedExceptionTest {

    // Custom wrapper
    @FunctionalInterface
    interface ThrowingFunction<T, R> { R apply(T t) throws Exception; }

    static <T, R> Function<T, R> unchecked(ThrowingFunction<T, R> fn) {
        return t -> { try { return fn.apply(t); } catch (Exception e) { throw new RuntimeException(e); } };
    }

    String riskyParse(String s) throws Exception {
        if (s.equals("BAD")) throw new Exception("Parse failed for: " + s);
        return s.toUpperCase();
    }

    @Test
    void tryCatchInsideLambda() {
        List<String> result = List.of("good", "BAD", "fine").stream()
            .map(s -> {
                try { return riskyParse(s); }
                catch (Exception e) { return "ERROR"; }
            }).toList();
        assertThat(result).containsExactly("GOOD", "ERROR", "FINE");
    }

    @Test
    void uncheckedWrapper() {
        // Happy path:
        List<String> result = List.of("good", "fine").stream()
            .map(unchecked(this::riskyParse))
            .toList();
        assertThat(result).containsExactly("GOOD", "FINE");

        // Failure wraps in RuntimeException:
        assertThatThrownBy(() ->
            List.of("good", "BAD").stream().map(unchecked(this::riskyParse)).toList())
            .isInstanceOf(RuntimeException.class)
            .hasCauseInstanceOf(Exception.class);
    }
}
