package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.assertj.core.api.Assertions.assertThat;

class CheckedInLambdaTest {

    // helper converts checked -> unchecked so it fits a Function
    int parseAmount(String s) {
        try { return Integer.parseInt(s); }          // throws unchecked already
        catch (NumberFormatException e) { throw new IllegalArgumentException("bad: " + s, e); }
    }

    @Test
    void wrapCheckedAsUnchecked() {
        List<String> good = List.of("100", "200");
        int total = good.stream().mapToInt(this::parseAmount).sum();
        assertThat(total).isEqualTo(300);

        List<String> bad = List.of("100", "oops");
        assertThatThrownBy(() -> bad.stream().mapToInt(this::parseAmount).sum())
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessageContaining("bad: oops");
    }
}
